INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7365094, 1153979, 65858, '<td valign="top">Reminds me of a certain cowpocalypse (or maybe mcdonalds) shot. =) Creative, I like it!</td>', 'Reminds me of a certain cowpocalypse (or maybe mcdonalds) shot. =) Creative, I like it!', '2015-06-17 01:05:43.000000', NULL, 1),
(7365096, 1154584, 91342, '<td valign="top">Almost did this one myself</td>', 'Almost did this one myself', '2015-06-17 01:06:27.000000', NULL, 1),
(7365107, 1154189, 28276, '<td valign="top">I''m I the first to comment "don''t blink"?</td>', 'I''m I the first to comment "don''t blink"?', '2015-06-17 01:11:13.000000', NULL, 1),
(7365108, 1154480, 352, '<td valign="top">The lighting in the foreground is nice, but the sky in the back looks a bit blown out.  Great detail on the tree.</td>', 'The lighting in the foreground is nice, but the sky in the back looks a bit blown out.  Great detail on the tree.', '2015-06-17 01:11:19.000000', NULL, 1),
(7365110, 1154606, 65858, '<td valign="top">Maybe too much contrast. 4 from me, sorry.</td>', 'Maybe too much contrast. 4 from me, sorry.', '2015-06-17 01:11:41.000000', NULL, 1),
(7365114, 1153353, 65858, '<td valign="top">Pretty selection saturation, nice composition. 6 for now, may bump later.</td>', 'Pretty selection saturation, nice composition. 6 for now, may bump later.', '2015-06-17 01:12:47.000000', NULL, 1),
(7365118, 1154323, 65858, '<td valign="top">I guess that''s a bike graveyard. =) Interesting, but not too photogenic. 5 from me.</td>', 'I guess that''s a bike graveyard. =) Interesting, but not too photogenic. 5 from me.', '2015-06-17 01:14:03.000000', NULL, 1),
(7365119, 1154144, 138630, '<td valign="top">Excellent color and detail in this close-up.</td>', 'Excellent color and detail in this close-up.', '2015-06-17 01:14:08.000000', NULL, 1),
(7365122, 1153690, 65858, '<td valign="top">Seems like a bit of a stretch, but I like the silhouette effect. Wish the sunset action was a bit lower. 5 from me.</td>', 'Seems like a bit of a stretch, but I like the silhouette effect. Wish the sunset action was a bit lower. 5 from me.', '2015-06-17 01:15:18.000000', NULL, 1),
(7365124, 1154236, 352, '<td valign="top">y Nice clean horizon.  The background spires are all even, and the crop on them is nice as well.</td>', 'y Nice clean horizon.  The background spires are all even, and the crop on them is nice as well.', '2015-06-17 01:15:34.000000', NULL, 1),
(7365127, 1154351, 65858, '<td valign="top">Cool image, points for creativity!</td>', 'Cool image, points for creativity!', '2015-06-17 01:16:09.000000', NULL, 1),
(7365128, 1154254, 138630, '<td valign="top">Good tones and light - eerie.</td>', 'Good tones and light - eerie.', '2015-06-17 01:16:19.000000', NULL, 1),
(7365129, 1154345, 352, '<td valign="top">The mist cloud is a nice touch.  If you made it with dry ice, the effect would be even better had you let it rise further up.</td>', 'The mist cloud is a nice touch.  If you made it with dry ice, the effect would be even better had you let it rise further up.', '2015-06-17 01:16:25.000000', NULL, 1),
(7365132, 1154298, 65858, '<td valign="top">Pretty colors, seems a little random -- peacock solemnly reading a headstone. =)</td>', 'Pretty colors, seems a little random -- peacock solemnly reading a headstone. =)', '2015-06-17 01:17:12.000000', NULL, 1),
(7365136, 1153744, 138630, '<td valign="top">So many markers and statues.  You did well to make just a few stand out.</td>', 'So many markers and statues.  You did well to make just a few stand out.', '2015-06-17 01:18:13.000000', NULL, 1),
(7365138, 1154347, 65858, '<td valign="top">I love the elements beyond the headstones in this one, nice work.</td>', 'I love the elements beyond the headstones in this one, nice work.', '2015-06-17 01:19:08.000000', NULL, 1),
(7365142, 1153412, 352, '<td valign="top">I can''t help but feel there''d be more emotion with this sky had you waited another 30-60 minutes to take the shot so the foreground weren''t so brightly lit.</td>', 'I can''t help but feel there''d be more emotion with this sky had you waited another 30-60 minutes to take the shot so the foreground weren''t so brightly lit.', '2015-06-17 01:20:33.000000', NULL, 1),
(7365143, 1154351, 138630, '<td valign="top">The panorama works well for showing the extent of this cemetery.</td>', 'The panorama works well for showing the extent of this cemetery.', '2015-06-17 01:20:58.000000', NULL, 1),
(7365146, 1154581, 352, '<td valign="top">The 05-02 tag doesn''t seem to be in as much focus as the rest of its casket and the one behind it.  Kind of expect it to be given your choice of title.</td>', 'The 05-02 tag doesn''t seem to be in as much focus as the rest of its casket and the one behind it.  Kind of expect it to be given your choice of title.', '2015-06-17 01:22:03.000000', NULL, 1),
(7365149, 1153116, 138630, '<td valign="top">This is a very nice find, well presented.  The statue is nicely framed by the tree, the cracked wall a good background.  I think you put a texture over it - works well to unify the whole as does the slightly pink tone.</td>', 'This is a very nice find, well presented.  The statue is nicely framed by the tree, the cracked wall a good background.  I think you put a texture over it - works well to unify the whole as does the slightly pink tone.', '2015-06-17 01:22:38.000000', NULL, 1),
(7365152, 1153975, 138630, '<td valign="top">Good job on the depth of field here - the skyscraper in the background of this very old marker is strangely haunting.</td>', 'Good job on the depth of field here - the skyscraper in the background of this very old marker is strangely haunting.', '2015-06-17 01:23:35.000000', NULL, 1),
(7365153, 1154551, 352, '<td valign="top">The crop on the top would have been better had it been even between left and right.  It could also stand to be rotated ever so slightly counter clockwise to even the horizon under the skulls since they bear so much of the weight of the photo.</td>', 'The crop on the top would have been better had it been even between left and right.  It could also stand to be rotated ever so slightly counter clockwise to even the horizon under the skulls since they bear so much of the weight of the photo.', '2015-06-17 01:24:45.000000', NULL, 1),
(7365158, 1154192, 352, '<td valign="top">Nice DOF, although the sepia treatment takes a bit away IMHO.</td>', 'Nice DOF, although the sepia treatment takes a bit away IMHO.', '2015-06-17 01:25:41.000000', NULL, 1),
(7365161, 1154467, 352, '<td valign="top">The blurred background gives me a sense of motion, which I don''t expect at all out of a graveyard.  Nice angling though!</td>', 'The blurred background gives me a sense of motion, which I don''t expect at all out of a graveyard.  Nice angling though!', '2015-06-17 01:26:34.000000', NULL, 1),
(7365164, 1154512, 352, '<td valign="top">Shame that the flowers underneath have been cropped out half way.  KInd of feel they should be either fully cropped or not at all.</td>', 'Shame that the flowers underneath have been cropped out half way.  KInd of feel they should be either fully cropped or not at all.', '2015-06-17 01:27:38.000000', NULL, 1),
(7365167, 1152893, 352, '<td valign="top">Nice application/use of sepia.</td>', 'Nice application/use of sepia.', '2015-06-17 01:28:16.000000', NULL, 1),
(7365170, 1153955, 138630, '<td valign="top">I like the freshness of this one.</td>', 'I like the freshness of this one.', '2015-06-17 01:29:51.000000', NULL, 1),
(7365171, 1153406, 180676, '<td valign="top">Would love to see a little more separation between your model and the headstone, but nice shot!</td>', 'Would love to see a little more separation between your model and the headstone, but nice shot!', '2015-06-17 01:29:54.000000', NULL, 1),
(7365172, 1153353, 352, '<td valign="top">The grain-iness bothers me.  Was this over processed?</td>', 'The grain-iness bothers me.  Was this over processed?', '2015-06-17 01:30:30.000000', NULL, 1),
(7365174, 1154591, 352, '<td valign="top">Gloomy!! :)</td>', 'Gloomy!! :)', '2015-06-17 01:31:10.000000', NULL, 1),
(7365179, 1152686, 180676, '<td valign="top">Now THAT is just flat out creepy!  Nice edit to get her to stand out, too!<br/> <br/>I''m gonna have nightmares about "Our Darling" now...</td>', 'Now THAT is just flat out creepy!  Nice edit to get her to stand out, too! I''m gonna have nightmares about "Our Darling" now...', '2015-06-17 01:31:58.000000', NULL, 1),
(7365189, 1154408, 138630, '<td valign="top">Very nice light.</td>', 'Very nice light.', '2015-06-17 01:34:35.000000', NULL, 1),
(7365194, 1154110, 138630, '<td valign="top">Very eye-catching and strangely beautiful.  The eerie look of the toned infrared is quite appropriate here.</td>', 'Very eye-catching and strangely beautiful.  The eerie look of the toned infrared is quite appropriate here.', '2015-06-17 01:36:08.000000', NULL, 1),
(7365195, 1154459, 138630, '<td valign="top">Beautiful glow and tones - love the way the grass heads dance in the light and breeze.</td>', 'Beautiful glow and tones - love the way the grass heads dance in the light and breeze.', '2015-06-17 01:36:56.000000', NULL, 1),
(7365197, 1154313, 138630, '<td valign="top">Macabre.</td>', 'Macabre.', '2015-06-17 01:37:18.000000', NULL, 1),
(7365199, 1154370, 180676, '<td valign="top">Nice perspective! (but would love it if the tombs were a bit brighter to draw the focus.)</td>', 'Nice perspective! (but would love it if the tombs were a bit brighter to draw the focus.)', '2015-06-17 01:38:02.000000', NULL, 1),
(7365203, 1154413, 138630, '<td valign="top">Yes, infrared works well for this subject.  I especially like the round leaves in the upper left corner.</td>', 'Yes, infrared works well for this subject.  I especially like the round leaves in the upper left corner.', '2015-06-17 01:41:37.000000', NULL, 1),
(7365204, 1154071, 352, '<td valign="top">Not at all a fan of your processing on this one.</td>', 'Not at all a fan of your processing on this one.', '2015-06-17 01:42:17.000000', NULL, 1),
(7365205, 1154444, 138630, '<td valign="top">Never seen anything like this.  So stately.</td>', 'Never seen anything like this.  So stately.', '2015-06-17 01:43:52.000000', NULL, 1),
(7365209, 1154301, 138630, '<td valign="top">Beautiful - the simple crystal (or is it metal?) is enough in this glorious setting.  Love the blues.</td>', 'Beautiful - the simple crystal (or is it metal?) is enough in this glorious setting.  Love the blues.', '2015-06-17 01:45:03.000000', NULL, 1),
(7365210, 1154334, 352, '<td valign="top">Nice DOF</td>', 'Nice DOF', '2015-06-17 01:45:06.000000', NULL, 1),
(7365214, 1154321, 138630, '<td valign="top">I love the tones and the textures here as well as the depth of field.  Too much sky for me.</td>', 'I love the tones and the textures here as well as the depth of field.  Too much sky for me.', '2015-06-17 01:46:54.000000', NULL, 1),
(7365215, 1153042, 138630, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2015-06-17 01:47:59.000000', NULL, 1),
(7365218, 1154078, 138630, '<td valign="top">Great tones.  Has the feel of a village, somehow.</td>', 'Great tones.  Has the feel of a village, somehow.', '2015-06-17 01:49:08.000000', NULL, 1),
(7365219, 1154370, 138630, '<td valign="top">Nicely framed.</td>', 'Nicely framed.', '2015-06-17 01:49:28.000000', NULL, 1),
