(7365226, 1153080, 96915, '<td valign="top">The processing effects to the trees and bushes distracts me.</td>', 'The processing effects to the trees and bushes distracts me.', '2015-06-17 01:52:00.000000', NULL, 1),
(7365227, 1154324, 138630, '<td valign="top">Beautiful light and color.</td>', 'Beautiful light and color.', '2015-06-17 01:52:06.000000', NULL, 1),
(7365228, 1154330, 180676, '<td valign="top">Quite eerie, well done!  Gotta ask, was this done twilight, or after dark?</td>', 'Quite eerie, well done!  Gotta ask, was this done twilight, or after dark?', '2015-06-17 01:53:35.000000', NULL, 1),
(7365233, 1154011, 96915, '<td valign="top">Beautiful light and colors.  Happy even.</td>', 'Beautiful light and colors.  Happy even.', '2015-06-17 01:57:00.000000', NULL, 1),
(7365246, 1154480, 180170, '<td valign="top">I love the tree and the lights really nice. Good Job</td>', 'I love the tree and the lights really nice. Good Job', '2015-06-17 02:10:14.000000', NULL, 1),
(7365247, 1153703, 180170, '<td valign="top">Fantastic sky and I love the post processing, well done.</td>', 'Fantastic sky and I love the post processing, well done.', '2015-06-17 02:11:30.000000', NULL, 1),
(7365248, 1153276, 180170, '<td valign="top">nice shot, this looks great in black and white, well done</td>', 'nice shot, this looks great in black and white, well done', '2015-06-17 02:12:37.000000', NULL, 1),
(7365250, 1154154, 180170, '<td valign="top">nice d.o.f, looks great in black and white.  Trees frame it nicely. good job :)</td>', 'nice d.o.f, looks great in black and white.  Trees frame it nicely. good job :)', '2015-06-17 02:14:34.000000', NULL, 1),
(7365252, 1153920, 180170, '<td valign="top">Fab sky. I would of liked it if you framed the cross more to the right so we could see even more of the sky using the rule of thirds, but its still a good shot, well done :)</td>', 'Fab sky. I would of liked it if you framed the cross more to the right so we could see even more of the sky using the rule of thirds, but its still a good shot, well done :)', '2015-06-17 02:17:08.000000', NULL, 1),
(7365255, 1153252, 180170, '<td valign="top">Oh, wow, how cool is that!! nice one :)</td>', 'Oh, wow, how cool is that!! nice one :)', '2015-06-17 02:19:20.000000', NULL, 1),
(7365257, 1152712, 180170, '<td valign="top">So wheres the rest of him ;) great shot, good use of rule of thirds, dof. Well done</td>', 'So wheres the rest of him ;) great shot, good use of rule of thirds, dof. Well done', '2015-06-17 02:21:34.000000', NULL, 1),
(7365263, 1154370, 180170, '<td valign="top">ooh nice ) love the way youve framed it with the arch :D</td>', 'ooh nice ) love the way youve framed it with the arch :D', '2015-06-17 02:25:29.000000', NULL, 1),
