(7367100, 1154236, 16046, '<td valign="top">Best in show award, congrats</td>', 'Best in show award, congrats', '2015-06-19 12:48:47.000000', NULL, 1),
(7367101, 1154110, 16046, '<td valign="top">Top 2</td>', 'Top 2', '2015-06-19 12:49:07.000000', NULL, 1),
(7367173, 1153263, 34171, '<td valign="top">The fog makes it more mysterious.</td>', 'The fog makes it more mysterious.', '2015-06-19 14:23:15.000000', NULL, 1),
(7367175, 1154603, 34171, '<td valign="top">Nice comp and great old stones.</td>', 'Nice comp and great old stones.', '2015-06-19 14:23:55.000000', NULL, 1),
(7367177, 1154241, 34171, '<td valign="top">Interesting take on this challenge.  Not an inside the box thinker, I like that.</td>', 'Interesting take on this challenge.  Not an inside the box thinker, I like that.', '2015-06-19 14:24:58.000000', NULL, 1),
(7367179, 1154488, 34171, '<td valign="top">RIP Harley.</td>', 'RIP Harley.', '2015-06-19 14:25:24.000000', NULL, 1),
(7367182, 1154609, 34171, '<td valign="top">A hard scene to capture, especially with a moving deer in it.</td>', 'A hard scene to capture, especially with a moving deer in it.', '2015-06-19 14:26:14.000000', NULL, 1),
(7367185, 1153703, 34171, '<td valign="top">Spooky.</td>', 'Spooky.', '2015-06-19 14:26:49.000000', NULL, 1),
(7367196, 1153869, 34171, '<td valign="top">I would have come in closer and try to cut out the power lines in the background.  You also seem to have an errant brush stroke going through they sky right above the grave stone.</td>', 'I would have come in closer and try to cut out the power lines in the background.  You also seem to have an errant brush stroke going through they sky right above the grave stone.', '2015-06-19 14:35:27.000000', NULL, 1),
(7367201, 1154461, 34171, '<td valign="top">A different composition would have been better, perhaps closer and looking at the stone from the right side (the direction of the light) which looks like it might have eliminated the bright sky in the background.</td>', 'A different composition would have been better, perhaps closer and looking at the stone from the right side (the direction of the light) which looks like it might have eliminated the bright sky in the background.', '2015-06-19 14:43:17.000000', NULL, 1),
(7367202, 1154602, 34171, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2015-06-19 14:43:38.000000', NULL, 1),
(7367203, 1153049, 34171, '<td valign="top">I''m not wild about the coloring (color IR?) of this image, but it''s a nice scene.</td>', 'I''m not wild about the coloring (color IR?) of this image, but it''s a nice scene.', '2015-06-19 14:44:49.000000', NULL, 1),
(7367209, 1153425, 34171, '<td valign="top">Good processing on this image, but a better comp. with a more defined focus point would keep the viewers interest longer.</td>', 'Good processing on this image, but a better comp. with a more defined focus point would keep the viewers interest longer.', '2015-06-19 14:49:19.000000', NULL, 1),
(7367210, 1154199, 34171, '<td valign="top">Good comp and processing.  I like.</td>', 'Good comp and processing.  I like.', '2015-06-19 14:49:53.000000', NULL, 1),
(7367211, 1154172, 34171, '<td valign="top">Different, I like it.</td>', 'Different, I like it.', '2015-06-19 14:50:47.000000', NULL, 1),
(7367214, 1154169, 34171, '<td valign="top">Nice processing.</td>', 'Nice processing.', '2015-06-19 14:51:28.000000', NULL, 1),
(7367218, 1154267, 34171, '<td valign="top">Hmmm is it to keep us out, or them in??</td>', 'Hmmm is it to keep us out, or them in??', '2015-06-19 14:52:33.000000', NULL, 1),
(7367221, 1154237, 34171, '<td valign="top">Well done.</td>', 'Well done.', '2015-06-19 14:53:23.000000', NULL, 1),
(7367257, 1154078, 34171, '<td valign="top">Well done.</td>', 'Well done.', '2015-06-19 15:17:46.000000', NULL, 1),
(7367259, 1152894, 34171, '<td valign="top">Love that statue, well done.</td>', 'Love that statue, well done.', '2015-06-19 15:18:38.000000', NULL, 1),
(7367340, 1154241, 68256, '<td valign="top">I have no clue what this means but I like the composition, textures, tone, etc.  What a strange, strange capture.</td>', 'I have no clue what this means but I like the composition, textures, tone, etc.  What a strange, strange capture.', '2015-06-19 16:28:58.000000', NULL, 1),
(7367341, 1153261, 68256, '<td valign="top">I really like the "watercolorness" of this...the toy is just sad :(.  Good job.</td>', 'I really like the "watercolorness" of this...the toy is just sad :(.  Good job.', '2015-06-19 16:29:57.000000', NULL, 1),
(7367342, 1154078, 68256, '<td valign="top">Great job capturing the mood of this place. I really love the tones....</td>', 'Great job capturing the mood of this place. I really love the tones....', '2015-06-19 16:30:43.000000', NULL, 1),
(7367344, 1153564, 68256, '<td valign="top">That is sad...full Dr. Pepper in the back, beer in the front...and the lurking text..I hope this was setup and not found this way....good find either way and makes you think.</td>', 'That is sad...full Dr. Pepper in the back, beer in the front...and the lurking text..I hope this was setup and not found this way....good find either way and makes you think.', '2015-06-19 16:32:15.000000', NULL, 1),
(7367345, 1154595, 68256, '<td valign="top">Not a big fan of the blue tones and there isn''t anything that jumps out of the photo to me story wise.</td>', 'Not a big fan of the blue tones and there isn''t anything that jumps out of the photo to me story wise.', '2015-06-19 16:34:09.000000', NULL, 1),
(7367347, 1153042, 68256, '<td valign="top">Strange IR processing, but It kinda works I guess..makes the scene look cinematic.</td>', 'Strange IR processing, but It kinda works I guess..makes the scene look cinematic.', '2015-06-19 16:35:51.000000', NULL, 1),
(7367348, 1154497, 68256, '<td valign="top">Not a big fan of the green toning and the slight "HDR" look doesn''t quite work.  It might have worked better for me if there was more separation between the forground stone and trees.  Also, the blue halo at the top looks strange..I guess a result of HDR like processing?</td>', 'Not a big fan of the green toning and the slight "HDR" look doesn''t quite work.  It might have worked better for me if there was more separation between the forground stone and trees.  Also, the blue halo at the top looks strange..I guess a result of HDR like processing?', '2015-06-19 16:38:37.000000', NULL, 1),
(7367350, 1153864, 68256, '<td valign="top">You''ve made a good composition out of a terrible topic...good job.  Low angle, shapes, tone, etc...all work in this.</td>', 'You''ve made a good composition out of a terrible topic...good job.  Low angle, shapes, tone, etc...all work in this.', '2015-06-19 16:40:08.000000', NULL, 1),
(7367352, 1154334, 68256, '<td valign="top">I like the warm tones and the grass adds a nice touch.  Also great textures and subject placement.  Good job.  Since there is no personal connection or meaning it''s hard for me to go above a 6 but it is well done and deserves good votes.</td>', 'I like the warm tones and the grass adds a nice touch.  Also great textures and subject placement.  Good job.  Since there is no personal connection or meaning it''s hard for me to go above a 6 but it is well done and deserves good votes.', '2015-06-19 16:42:36.000000', NULL, 1),
(7367354, 1154408, 68256, '<td valign="top">Really nice composition..I love the natural tones and washed sun look....I do wish the bench had some support on the viewers left side but other than that it works great.</td>', 'Really nice composition..I love the natural tones and washed sun look....I do wish the bench had some support on the viewers left side but other than that it works great.', '2015-06-19 16:44:10.000000', NULL, 1),
(7367359, 1154311, 68256, '<td valign="top">Good job with the composition.  I wished the DOF was a little shallower to create more division between the subjects and the background but that may have been the limit of your equipment.  I guess you may have also been worried about context for the challenge to and "seeing" the rest of the graveyard in the background may help.  I''m just saying for me personally I would like to have it blurred more. Love the textures by the way....</td>', 'Good job with the composition.  I wished the DOF was a little shallower to create more division between the subjects and the background but that may have been the limit of your equipment.  I guess you may have also been worried about context for the challenge to and "seeing" the rest of the graveyard in the background may help.  I''m just saying for me personally I would like to have it blurred more. Love the textures by the way....', '2015-06-19 16:46:38.000000', NULL, 1),
(7367362, 1154436, 68256, '<td valign="top">Very creepy and well done flash ghosting...not a fan of the angled view but that''s just me....</td>', 'Very creepy and well done flash ghosting...not a fan of the angled view but that''s just me....', '2015-06-19 16:47:49.000000', NULL, 1),
(7367481, 1154601, 16106, '<td valign="top">The colors look off to me. The stone is lovely but looks like it is made out of gingerbread. The background is OK, it tells us we are in a graveyard but not much more, so I wish we had more of that beautiful headstone and less of the rest.</td>', 'The colors look off to me. The stone is lovely but looks like it is made out of gingerbread. The background is OK, it tells us we are in a graveyard but not much more, so I wish we had more of that beautiful headstone and less of the rest.', '2015-06-19 19:40:27.000000', NULL, 1),
(7367483, 1154313, 16106, '<td valign="top">It is a lovely set up, and the addition of the bug is great, but I am in no way convinced that this is in a graveyard. It is a better photograph than an entry in this challenge if that makes any sense.</td>', 'It is a lovely set up, and the addition of the bug is great, but I am in no way convinced that this is in a graveyard. It is a better photograph than an entry in this challenge if that makes any sense.', '2015-06-19 19:42:40.000000', NULL, 1),
(7367484, 1154551, 16106, '<td valign="top">Nice find but the most interest us up at those skulls squeezed along the top of the frame. on my monitor a few of the edges are lost in the high key editing and a bit more darkness would have helped.</td>', 'Nice find but the most interest us up at those skulls squeezed along the top of the frame. on my monitor a few of the edges are lost in the high key editing and a bit more darkness would have helped.', '2015-06-19 19:44:54.000000', NULL, 1),
(7367486, 1154469, 16106, '<td valign="top">Beautiful clarity  but I wish there was more context that you gave us.</td>', 'Beautiful clarity  but I wish there was more context that you gave us.', '2015-06-19 19:45:59.000000', NULL, 1),
(7367487, 1154374, 16106, '<td valign="top">good depth and nice tones, should do well.</td>', 'good depth and nice tones, should do well.', '2015-06-19 19:46:36.000000', NULL, 1),
(7367489, 1154187, 16106, '<td valign="top">I like the softness of the stones in the back but the foreground has so little information due to the decay of age that I am left wondering what I am supposed to be looking at. The stones behind are squeezed so hard in your framing that I get the felling I am being forced to find information I just am not getting. Nice tones in your B&amp;W and a restful sense but for the pressurized framing.</td>', 'I like the softness of the stones in the back but the foreground has so little information due to the decay of age that I am left wondering what I am supposed to be looking at. The stones behind are squeezed so hard in your framing that I get the felling I am being forced to find information I just am not getting. Nice tones in your B&W and a restful sense but for the pressurized framing.', '2015-06-19 19:50:31.000000', NULL, 1),
(7367491, 1153276, 16106, '<td valign="top">Nice entry, though the keystoning pulls the eye out to the right to no purpose I can see. had you squared that up with a skew, it would have been best yet. The historical irony is pretty impressive.</td>', 'Nice entry, though the keystoning pulls the eye out to the right to no purpose I can see. had you squared that up with a skew, it would have been best yet. The historical irony is pretty impressive.', '2015-06-19 19:52:44.000000', NULL, 1),
(7367492, 1154584, 16106, '<td valign="top">overall the image seems a bit cluttered. the pastel tones of the toys and the marker are strong, but the two informational plaques on the left that I can not read don''t add any value. Closer in, further back? there are the bones of a solid shot here, but many distractions that pull the eye here and there.</td>', 'overall the image seems a bit cluttered. the pastel tones of the toys and the marker are strong, but the two informational plaques on the left that I can not read don''t add any value. Closer in, further back? there are the bones of a solid shot here, but many distractions that pull the eye here and there.', '2015-06-19 19:56:16.000000', NULL, 1),
(7367493, 1154030, 16106, '<td valign="top">Blunt, solid and moody. Best yet.</td>', 'Blunt, solid and moody. Best yet.', '2015-06-19 19:56:45.000000', NULL, 1),
(7367495, 1154305, 16106, '<td valign="top">I get a notion of what this place is like from this picture, but I want to go up and look around, to see something special. What we have here is too generic. Making the tree the star puzzles me since it isn''t a terribly lovely tree.</td>', 'I get a notion of what this place is like from this picture, but I want to go up and look around, to see something special. What we have here is too generic. Making the tree the star puzzles me since it isn''t a terribly lovely tree.', '2015-06-19 19:59:44.000000', NULL, 1),
(7367496, 1154436, 16106, '<td valign="top">hokey concept very well done, among my favorites so far. I wish there was a bit more than blocked up blacks on the left, but the ghost and stone are nails.</td>', 'hokey concept very well done, among my favorites so far. I wish there was a bit more than blocked up blacks on the left, but the ghost and stone are nails.', '2015-06-19 20:00:59.000000', NULL, 1),
(7367505, 1153511, 11854, '<td valign="top">And what a lovely view it is. It''s a shame not to many get to see it. This looks like an old, old place. Well taken!</td>', 'And what a lovely view it is. It''s a shame not to many get to see it. This looks like an old, old place. Well taken!', '2015-06-19 20:38:52.000000', NULL, 1),
(7367507, 1154436, 11854, '<td valign="top">Beautifully done. It tugs my heartstrings as these photos are hard for me to look at right now.</td>', 'Beautifully done. It tugs my heartstrings as these photos are hard for me to look at right now.', '2015-06-19 20:40:38.000000', NULL, 1),
(7367509, 1153083, 11854, '<td valign="top">So uniform. It really makes you think.</td>', 'So uniform. It really makes you think.', '2015-06-19 20:42:15.000000', NULL, 1),
(7367510, 1154476, 11854, '<td valign="top">Mother will not be lonely.</td>', 'Mother will not be lonely.', '2015-06-19 20:43:01.000000', NULL, 1),
(7367511, 1153864, 11854, '<td valign="top">I''m glad it''s not of the Stephen King variety.</td>', 'I''m glad it''s not of the Stephen King variety.', '2015-06-19 20:43:37.000000', NULL, 1),
(7367512, 1153252, 11854, '<td valign="top">How sweet.</td>', 'How sweet.', '2015-06-19 20:43:56.000000', NULL, 1),
(7367514, 1154330, 11854, '<td valign="top">Beautifully done.</td>', 'Beautifully done.', '2015-06-19 20:45:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7367515, 1154169, 11854, '<td valign="top">Gorgeous treatment.</td>', 'Gorgeous treatment.', '2015-06-19 20:45:29.000000', NULL, 1),
(7367516, 1153955, 11854, '<td valign="top">Literally! What a catch!</td>', 'Literally! What a catch!', '2015-06-19 20:46:47.000000', NULL, 1),
(7367518, 1154317, 11854, '<td valign="top">This really touches me.</td>', 'This really touches me.', '2015-06-19 20:48:34.000000', NULL, 1),
(7367519, 1154408, 11854, '<td valign="top">They can be such peaceful, beautiful places.</td>', 'They can be such peaceful, beautiful places.', '2015-06-19 20:49:04.000000', NULL, 1),
(7367545, 1153920, 62249, '<td valign="top">Too much sharpening around edge of monument, resulting in a visible halo. But otherwise a pleasant shot.</td>', 'Too much sharpening around edge of monument, resulting in a visible halo. But otherwise a pleasant shot.', '2015-06-19 21:50:58.000000', NULL, 1),
(7367548, 1153261, 62249, '<td valign="top">Interesting processing choice that works pretty well with the image. The image would be even stronger if there were only one main subject. As is, I''m not quite sure whether to look at the toy, the headstone on the left, or the cross. Also, the spot of red amid the trees in the background catches my eye.</td>', 'Interesting processing choice that works pretty well with the image. The image would be even stronger if there were only one main subject. As is, I''m not quite sure whether to look at the toy, the headstone on the left, or the cross. Also, the spot of red amid the trees in the background catches my eye.', '2015-06-19 21:54:28.000000', NULL, 1),
(7367549, 1154096, 62249, '<td valign="top">The flowers are pretty. Watch out for blown highlights on the rose below NINA. The dappled light on the reflective headstone is distracting, but also tricky to deal with.</td>', 'The flowers are pretty. Watch out for blown highlights on the rose below NINA. The dappled light on the reflective headstone is distracting, but also tricky to deal with.', '2015-06-19 21:57:01.000000', NULL, 1),
(7367550, 1152894, 62249, '<td valign="top">I find the leaves in the upper part of the image even more interesting than the statue :-).</td>', 'I find the leaves in the upper part of the image even more interesting than the statue :-).', '2015-06-19 21:58:09.000000', NULL, 1),
(7367551, 1153778, 62249, '<td valign="top">Especially given your title for the image, I think the image could have been improved by pumping up the contrast so that your white areas are much brighter instead of a murky gray.</td>', 'Especially given your title for the image, I think the image could have been improved by pumping up the contrast so that your white areas are much brighter instead of a murky gray.', '2015-06-19 22:00:02.000000', NULL, 1),
(7367554, 1153776, 62249, '<td valign="top">A cool-looking cross. A bit of supplemental lighting on the cross, or at least some dodging to lighten it, would make for a more dramatic presentation.</td>', 'A cool-looking cross. A bit of supplemental lighting on the cross, or at least some dodging to lighten it, would make for a more dramatic presentation.', '2015-06-19 22:01:28.000000', NULL, 1),
(7367555, 1153739, 62249, '<td valign="top">Graveyards aren''t usually funny, but this cracks me up. Good humor and good use of lens flare too.</td>', 'Graveyards aren''t usually funny, but this cracks me up. Good humor and good use of lens flare too.', '2015-06-19 22:03:28.000000', NULL, 1),
(7367567, 1154323, 96915, '<td valign="top">Thank you, I needed a break from all the headstones.  I would have liked this more as a close up, without the bridge in the background, and gentler lighting (the reflectors make me think a flash was used?)</td>', 'Thank you, I needed a break from all the headstones.  I would have liked this more as a close up, without the bridge in the background, and gentler lighting (the reflectors make me think a flash was used?)', '2015-06-19 22:45:45.000000', NULL, 1),
(7367602, 1154591, 30982, '<td valign="top">Harsh processing - looks almost like a metalic print.  Kinda spooky!</td>', 'Harsh processing - looks almost like a metalic print.  Kinda spooky!', '2015-06-20 01:12:59.000000', NULL, 1),
(7367603, 1154394, 30982, '<td valign="top">Ha!  Great title.  I like the fact Darth Vader is nearby, too.</td>', 'Ha!  Great title.  I like the fact Darth Vader is nearby, too.', '2015-06-20 01:13:17.000000', NULL, 1),
(7367604, 1154317, 30982, '<td valign="top">It appears as though he was born in 1831, so he''d be a bit old to be her husband, but I like the sentiment.  Nice to add a person to the shot.</td>', 'It appears as though he was born in 1831, so he''d be a bit old to be her husband, but I like the sentiment.  Nice to add a person to the shot.', '2015-06-20 01:15:10.000000', NULL, 1),
(7367605, 1154543, 30982, '<td valign="top">It''s hard (at least for me) to get a good shot inside a masoleum or crypt.  The straight on approach here is good for showing the structure, but a bit static.  I don''t know if a different angle would be better, but might be something to try should you ever again want to shoot a masoleum!</td>', 'It''s hard (at least for me) to get a good shot inside a masoleum or crypt.  The straight on approach here is good for showing the structure, but a bit static.  I don''t know if a different angle would be better, but might be something to try should you ever again want to shoot a masoleum!', '2015-06-20 01:16:37.000000', NULL, 1),
(7367607, 1154529, 30982, '<td valign="top">A good direct straight-on recording.  Interesting how some stand out more than others.  Lovely trees, too.</td>', 'A good direct straight-on recording.  Interesting how some stand out more than others.  Lovely trees, too.', '2015-06-20 01:17:21.000000', NULL, 1),
(7367608, 1153409, 30982, '<td valign="top">Very bold and bright, with interesting structures!  I wonder if it''s unkempt on purpose or if it has just been neglected.</td>', 'Very bold and bright, with interesting structures!  I wonder if it''s unkempt on purpose or if it has just been neglected.', '2015-06-20 01:18:00.000000', NULL, 1),
(7367611, 1154410, 30982, '<td valign="top">I''m sure there''s a story behind this... I like the ghosted girls, but the pose of the one in the foreground feels a bit stilted, though I realize you''re trying to show her running away.</td>', 'I''m sure there''s a story behind this... I like the ghosted girls, but the pose of the one in the foreground feels a bit stilted, though I realize you''re trying to show her running away.', '2015-06-20 01:19:32.000000', NULL, 1),
(7367612, 1153794, 30982, '<td valign="top">What a lovely location for a grave.  I like the screaming tree behind.</td>', 'What a lovely location for a grave.  I like the screaming tree behind.', '2015-06-20 01:20:04.000000', NULL, 1),
(7367613, 1154189, 30982, '<td valign="top">A bit static - maybe a more angled approach to the angel?  I find myself more interested in seeing what''s beyond, over to the right.  But I do like the detail in the statue.</td>', 'A bit static - maybe a more angled approach to the angel?  I find myself more interested in seeing what''s beyond, over to the right.  But I do like the detail in the statue.', '2015-06-20 01:21:06.000000', NULL, 1),
(7367614, 1154506, 30982, '<td valign="top">Good use of a strong leading line, but a bit harsh to me on the processing - it probably was a bright day and you''ve tried to tone it down a bit, which created some halos on the tree line.  This looks like a gorgeous cemetery.</td>', 'Good use of a strong leading line, but a bit harsh to me on the processing - it probably was a bright day and you''ve tried to tone it down a bit, which created some halos on the tree line.  This looks like a gorgeous cemetery.', '2015-06-20 01:23:29.000000', NULL, 1),
(7367615, 1153955, 30982, '<td valign="top">Best pun for a title.  I like the shot, too - that''s one old headstone.</td>', 'Best pun for a title.  I like the shot, too - that''s one old headstone.', '2015-06-20 01:24:46.000000', NULL, 1),
(7367616, 1154311, 30982, '<td valign="top">A wee bit creepy, but sweet!</td>', 'A wee bit creepy, but sweet!', '2015-06-20 01:25:13.000000', NULL, 1),
(7367617, 1153506, 30982, '<td valign="top">This is hauntingly gorgeous.  Thanks for a very different sort of entry.</td>', 'This is hauntingly gorgeous.  Thanks for a very different sort of entry.', '2015-06-20 01:26:44.000000', NULL, 1),
(7367618, 1154101, 30982, '<td valign="top">Went away Monday evening, she did.  Didn''t live very long but certainly has an elegant tombstone.</td>', 'Went away Monday evening, she did.  Didn''t live very long but certainly has an elegant tombstone.', '2015-06-20 01:27:59.000000', NULL, 1),
(7367619, 1152686, 30982, '<td valign="top">Our Darling looks quite grumpy - almost evil.  But it''s a fascinating graveyard.</td>', 'Our Darling looks quite grumpy - almost evil.  But it''s a fascinating graveyard.', '2015-06-20 01:28:57.000000', NULL, 1),
(7367620, 1154557, 30982, '<td valign="top">Nice use of what appears to be a Lensbaby type device.</td>', 'Nice use of what appears to be a Lensbaby type device.', '2015-06-20 01:29:23.000000', NULL, 1),
(7367621, 1153083, 30982, '<td valign="top">Those three markers seem so out of place.  Great view - love including the leafblower guy.</td>', 'Those three markers seem so out of place.  Great view - love including the leafblower guy.', '2015-06-20 01:30:27.000000', NULL, 1),
(7367794, 1153564, 62249, '<td valign="top">The composition contains too many different things to look at : the headstone, the can of PBR, the bottle, and the flagpole in the background.</td>', 'The composition contains too many different things to look at : the headstone, the can of PBR, the bottle, and the flagpole in the background.', '2015-06-20 12:53:14.000000', NULL, 1),
(7367795, 1154401, 62249, '<td valign="top">Straight head-on shots like this don''t tend to be very interesting. They are documentary but not artistic. Focus also seems a little soft.</td>', 'Straight head-on shots like this don''t tend to be very interesting. They are documentary but not artistic. Focus also seems a little soft.', '2015-06-20 12:54:23.000000', NULL, 1),
(7367796, 1154582, 62249, '<td valign="top">Needs a stronger composition. Scene is too chaotic and doesn''t draw the viewer''s attention to any one thing.</td>', 'Needs a stronger composition. Scene is too chaotic and doesn''t draw the viewer''s attention to any one thing.', '2015-06-20 12:55:17.000000', NULL, 1),
(7367797, 1154199, 62249, '<td valign="top">Good use of layering the foreground, middle area, background.</td>', 'Good use of layering the foreground, middle area, background.', '2015-06-20 12:56:00.000000', NULL, 1),
(7367799, 1153412, 62249, '<td valign="top">Lighting is nice. Either step closer or crop out some of the foreground grass.</td>', 'Lighting is nice. Either step closer or crop out some of the foreground grass.', '2015-06-20 12:57:23.000000', NULL, 1),
(7367801, 1153222, 62249, '<td valign="top">It''s fun to play with selective saturation/desaturation. In this case, there are extraneous bits of flower petals that should''ve been converted to gray instead of being left red. The red chunk between the two top blooms is one example. The same thing happens between and near the foreground pair of red flowers, and the stray bits on the top headstone are also distracting.</td>', 'It''s fun to play with selective saturation/desaturation. In this case, there are extraneous bits of flower petals that should''ve been converted to gray instead of being left red. The red chunk between the two top blooms is one example. The same thing happens between and near the foreground pair of red flowers, and the stray bits on the top headstone are also distracting.', '2015-06-20 13:02:08.000000', NULL, 1),
(7367802, 1154374, 62249, '<td valign="top">I like the dreaminess of this one. One nitpick: wish you had crouched just a tad lower so that the right edge of the crossbar on the cross didn''t intersect the top of the headstone behind it.</td>', 'I like the dreaminess of this one. One nitpick: wish you had crouched just a tad lower so that the right edge of the crossbar on the cross didn''t intersect the top of the headstone behind it.', '2015-06-20 13:04:39.000000', NULL, 1),
(7367804, 1154243, 62249, '<td valign="top">While the processing gives a dramatic look, you''ve pushed it to the point where there are unpleasant halos around the tree branches and along the edge of the treelike in the background.</td>', 'While the processing gives a dramatic look, you''ve pushed it to the point where there are unpleasant halos around the tree branches and along the edge of the treelike in the background.', '2015-06-20 13:06:25.000000', NULL, 1),
(7367805, 1154322, 62249, '<td valign="top">I suggest cropping out the flowers along the left edge of the scene because they distract from the otherwise well composed scene.</td>', 'I suggest cropping out the flowers along the left edge of the scene because they distract from the otherwise well composed scene.', '2015-06-20 13:09:08.000000', NULL, 1),
(7367806, 1153243, 62249, '<td valign="top">I like the very low horizon line. Wish there was a single compositional element that grabbed the viewer''s eye to say "I am the subject."</td>', 'I like the very low horizon line. Wish there was a single compositional element that grabbed the viewer''s eye to say "I am the subject."', '2015-06-20 13:17:07.000000', NULL, 1),
(7367808, 1154586, 62249, '<td valign="top">Like the dramatic sky. Focus seems a bit soft.</td>', 'Like the dramatic sky. Focus seems a bit soft.', '2015-06-20 13:17:55.000000', NULL, 1),
(7367809, 1154169, 62249, '<td valign="top">The HDR processing is a bit overdone, but it''s still a lovely image.</td>', 'The HDR processing is a bit overdone, but it''s still a lovely image.', '2015-06-20 13:20:05.000000', NULL, 1),
(7367811, 1153690, 62249, '<td valign="top">A creative take on the challenge. Straighten the horizon, and make sure your focus is sharp on the subject.</td>', 'A creative take on the challenge. Straighten the horizon, and make sure your focus is sharp on the subject.', '2015-06-20 13:22:12.000000', NULL, 1),
(7367813, 1154394, 62249, '<td valign="top">Good title.</td>', 'Good title.', '2015-06-20 13:23:20.000000', NULL, 1),
(7367814, 1154264, 62249, '<td valign="top">Good title. Grass looks oversaturated.</td>', 'Good title. Grass looks oversaturated.', '2015-06-20 13:24:53.000000', NULL, 1),
