(7370131, 1154496, 30982, '<td valign="top">I can see this on the interwebs with "And then THIS appeared!"... The overlay is a bit strong for me.</td>', 'I can see this on the interwebs with "And then THIS appeared!"... The overlay is a bit strong for me.', '2015-06-23 01:00:02.000000', NULL, 1),
(7370132, 1153864, 30982, '<td valign="top">I like that they all have their own lot number.  Interesting that this dates back to the 20s.</td>', 'I like that they all have their own lot number.  Interesting that this dates back to the 20s.', '2015-06-23 01:00:49.000000', NULL, 1),
(7370137, 1153821, 30982, '<td valign="top">Lovely.</td>', 'Lovely.', '2015-06-23 01:04:44.000000', NULL, 1),
(7370143, 1154459, 30982, '<td valign="top">The soft light, shallow DOF, partial headstone - all good choices that come together well here.</td>', 'The soft light, shallow DOF, partial headstone - all good choices that come together well here.', '2015-06-23 01:08:09.000000', NULL, 1),
(7370144, 1153586, 30982, '<td valign="top">Your model did an awesome job!</td>', 'Your model did an awesome job!', '2015-06-23 01:09:26.000000', NULL, 1),
(7370276, 1153533, 177322, '<td valign="top">Lovely, cheery colors.  Effective composition.  Great textures amongst the stones and the flora.</td>', 'Lovely, cheery colors.  Effective composition.  Great textures amongst the stones and the flora.', '2015-06-23 10:23:44.000000', NULL, 1),
(7370277, 1154541, 177322, '<td valign="top">While this appears to be incredibly ancient, it is interesting that you have captured the fact that someone sill visits it and leaves tokens. A noteworthy image.  Good luck.</td>', 'While this appears to be incredibly ancient, it is interesting that you have captured the fact that someone sill visits it and leaves tokens. A noteworthy image.  Good luck.', '2015-06-23 10:25:23.000000', NULL, 1),
(7370278, 1154169, 177322, '<td valign="top">Beautiful work.  B&amp;W really adds strength to the statement.  Good luck.</td>', 'Beautiful work.  B&W really adds strength to the statement.  Good luck.', '2015-06-23 10:26:29.000000', NULL, 1),
(7370279, 1154586, 177322, '<td valign="top">The harsh sun on those left stones is somewhat of a temporary distraction but once the eye reaches that wonderfully black stormy sky coupled with the message - and title - this becomes a powerful statement.  I, personally, might have cloned out the transformers on that pole to the right, but, honestly, I only discovered them upon studying the image meticulously.</td>', 'The harsh sun on those left stones is somewhat of a temporary distraction but once the eye reaches that wonderfully black stormy sky coupled with the message - and title - this becomes a powerful statement.  I, personally, might have cloned out the transformers on that pole to the right, but, honestly, I only discovered them upon studying the image meticulously.', '2015-06-23 10:30:26.000000', NULL, 1),
(7370284, 1152686, 114285, '<td valign="top">Powerful statue!</td>', 'Powerful statue!', '2015-06-23 10:41:21.000000', NULL, 1),
(7370285, 1154330, 114285, '<td valign="top">Brilliantly done!</td>', 'Brilliantly done!', '2015-06-23 10:42:05.000000', NULL, 1),
(7370286, 1153739, 114285, '<td valign="top">Funny sign, great light!</td>', 'Funny sign, great light!', '2015-06-23 10:42:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7370287, 1154408, 114285, '<td valign="top">Fantastic mood with the bright light!</td>', 'Fantastic mood with the bright light!', '2015-06-23 10:46:19.000000', NULL, 1),
(7370289, 1153406, 114285, '<td valign="top">The blue I reckon, haunting!</td>', 'The blue I reckon, haunting!', '2015-06-23 10:47:31.000000', NULL, 1),
(7370296, 1154517, 77196, '<td valign="top">For me, the dead tree(s) make this image - reaching out all over the place, touching the top of the headstone, tendrils, reaching, grasping, pointing. In addition, the contrast in this image is just right - not too stark, not too uniform. It creates just the right feel. It has a nice feel of depth to it as well.</td>', 'For me, the dead tree(s) make this image - reaching out all over the place, touching the top of the headstone, tendrils, reaching, grasping, pointing. In addition, the contrast in this image is just right - not too stark, not too uniform. It creates just the right feel. It has a nice feel of depth to it as well.', '2015-06-23 10:53:16.000000', NULL, 1),
(7370298, 1153320, 77196, '<td valign="top">Very disturbing image - subtle, but there is one too many hands in the picture, and the "blood" on her face leads the viewer to a rather grisly conclusion. Her "dress", her expression, the simple name on the tombstone, her bare feet - all disturbing. Great staging and execution.</td>', 'Very disturbing image - subtle, but there is one too many hands in the picture, and the "blood" on her face leads the viewer to a rather grisly conclusion. Her "dress", her expression, the simple name on the tombstone, her bare feet - all disturbing. Great staging and execution.', '2015-06-23 10:56:20.000000', NULL, 1),
(7370299, 1154030, 77196, '<td valign="top">I really liked the stark contrast and the simple marker.</td>', 'I really liked the stark contrast and the simple marker.', '2015-06-23 10:56:44.000000', NULL, 1),
(7370300, 1153406, 77196, '<td valign="top">Spooky and nicely done. I''m wondering if the light is a bit too much; looking too contrived. In contrast to the "transparent" ghostly figures, I like that he is very solid - adding to the impression of "real". The shadow of the central stone makes very nice leading lines.</td>', 'Spooky and nicely done. I''m wondering if the light is a bit too much; looking too contrived. In contrast to the "transparent" ghostly figures, I like that he is very solid - adding to the impression of "real". The shadow of the central stone makes very nice leading lines.', '2015-06-23 10:59:20.000000', NULL, 1),
(7370302, 1153330, 46918, '<td valign="top">I like the lighting on this one. The POV is also good. The crop is not bad but I probably would have brought it in slightly on the left</td>', 'I like the lighting on this one. The POV is also good. The crop is not bad but I probably would have brought it in slightly on the left', '2015-06-23 11:00:57.000000', NULL, 1),
(7370304, 1154324, 77196, '<td valign="top">One of the few real, positive, hopeful images in the challenge. I like how this does not deny the reality of death, but lifts one''s gaze beyond. The colors are warm and closer to cheerful than somber.</td>', 'One of the few real, positive, hopeful images in the challenge. I like how this does not deny the reality of death, but lifts one''s gaze beyond. The colors are warm and closer to cheerful than somber.', '2015-06-23 11:01:20.000000', NULL, 1),
(7370306, 1154480, 46918, '<td valign="top">This looks like a southern plantation. The sun / light in the background is a bit harsh and a little distracting</td>', 'This looks like a southern plantation. The sun / light in the background is a bit harsh and a little distracting', '2015-06-23 11:02:56.000000', NULL, 1),
(7370308, 1154496, 77196, '<td valign="top">Absolutely masterful. The "aged" image, the very subtle ghost, the combination of solid and real, but at the same time faded and questionable. The decorative iron fence in multiple rows adds to the not-quite-right feel.</td>', 'Absolutely masterful. The "aged" image, the very subtle ghost, the combination of solid and real, but at the same time faded and questionable. The decorative iron fence in multiple rows adds to the not-quite-right feel.', '2015-06-23 11:04:18.000000', NULL, 1),
(7370309, 1154078, 77196, '<td valign="top">Nothing quite as spooky as a cemetery in the moonlight. Great lighting and contrast, with a rather hodge-podge arrangement of memorials. Interestingly enough, the one with the rounded top is quite similar to one in a cemetery nearby. The obelisks add a rather interesting vertical dimension.</td>', 'Nothing quite as spooky as a cemetery in the moonlight. Great lighting and contrast, with a rather hodge-podge arrangement of memorials. Interestingly enough, the one with the rounded top is quite similar to one in a cemetery nearby. The obelisks add a rather interesting vertical dimension.', '2015-06-23 11:06:49.000000', NULL, 1),
(7370310, 1153116, 77196, '<td valign="top">I like the surreal effect captured here. The moss hanging from the tree adds to the feel.</td>', 'I like the surreal effect captured here. The moss hanging from the tree adds to the feel.', '2015-06-23 11:07:43.000000', NULL, 1),
(7370313, 1153083, 77196, '<td valign="top">What I find captivating about this image is the sense of motion to the markers - almost likes waves on the ocean. Not something you want to start at for a while, lest it start shifting around. Wasn''t sure I liked the worker with the leaf blower, but he''s not a major distraction, and is fairly easily dismissed mentally as being a part of the scene, rather than the sore thumb of my initial impression. <br/>On a more abstract level, there is something about the feel of this picture and the ebb and flow of life and death that makes a significant comment.</td>', 'What I find captivating about this image is the sense of motion to the markers - almost likes waves on the ocean. Not something you want to start at for a while, lest it start shifting around. Wasn''t sure I liked the worker with the leaf blower, but he''s not a major distraction, and is fairly easily dismissed mentally as being a part of the scene, rather than the sore thumb of my initial impression. On a more abstract level, there is something about the feel of this picture and the ebb and flow of life and death that makes a significant comment.', '2015-06-23 11:12:28.000000', NULL, 1),
(7370316, 1154330, 77196, '<td valign="top">Come on in, the water''s fine in this POOL. To me, the lady seems almost whimsical - I think it is the posture and the position of the hand. More like a child excited to explore a cave rather than a lady requesting entrance into the nether world. Great lighting, staging, and ghostly image capture.</td>', 'Come on in, the water''s fine in this POOL. To me, the lady seems almost whimsical - I think it is the posture and the position of the hand. More like a child excited to explore a cave rather than a lady requesting entrance into the nether world. Great lighting, staging, and ghostly image capture.', '2015-06-23 11:14:42.000000', NULL, 1),
(7370319, 1154317, 77196, '<td valign="top">Very poignant. For the happily married, one train of thought you avoid is the time when one will have to go on without their spouse. This image hits a bit too close to home. <br/>The single rose is a nice touch. But her posture is also saying so very much - not the immediate denial and shock of loss, not the angry questions of why, but the sad acceptance of the situation combined with a sadness of the loss of what was. Maybe even the power of love reaching across the gulf of death.</td>', 'Very poignant. For the happily married, one train of thought you avoid is the time when one will have to go on without their spouse. This image hits a bit too close to home. The single rose is a nice touch. But her posture is also saying so very much - not the immediate denial and shock of loss, not the angry questions of why, but the sad acceptance of the situation combined with a sadness of the loss of what was. Maybe even the power of love reaching across the gulf of death.', '2015-06-23 11:19:49.000000', NULL, 1),
(7370323, 1154567, 77196, '<td valign="top">Her hand touching the stone conveys a sense of need and a sense of abandonment. Where are you, Mom, and why have you left me? I need you. The posture contrasts with the lady''s obvious age. Very nice use of light and shadow to convey a somber, almost intense mood.</td>', 'Her hand touching the stone conveys a sense of need and a sense of abandonment. Where are you, Mom, and why have you left me? I need you. The posture contrasts with the lady''s obvious age. Very nice use of light and shadow to convey a somber, almost intense mood.', '2015-06-23 11:22:43.000000', NULL, 1),
(7370324, 1154308, 77196, '<td valign="top">The lighting on the memorials are a great contrast to the stormy sky.</td>', 'The lighting on the memorials are a great contrast to the stormy sky.', '2015-06-23 11:23:11.000000', NULL, 1),
(7370326, 1154591, 77196, '<td valign="top">I really like the mood of the picture - somber, but with the faces of the markers highlighted, combined with a sense of import, significance - like the dead aware of the present and watching - almost wanting to speak.</td>', 'I really like the mood of the picture - somber, but with the faces of the markers highlighted, combined with a sense of import, significance - like the dead aware of the present and watching - almost wanting to speak.', '2015-06-23 11:24:51.000000', NULL, 1),
(7370328, 1153866, 77196, '<td valign="top">I really like the lighting in this. It reminds me of the grave of Strider from Tolkein''s Lord of the Rings. Aged, but regal.</td>', 'I really like the lighting in this. It reminds me of the grave of Strider from Tolkein''s Lord of the Rings. Aged, but regal.', '2015-06-23 11:26:28.000000', NULL, 1),
(7370332, 1154459, 77196, '<td valign="top">I love the wispy-ness of this image. The lighting, the living grass in contrast to the old, weathered, hard stone. Somehow, for me, this is a hopeful image - that the cold hard reality of death is being swallowed by life and light.</td>', 'I love the wispy-ness of this image. The lighting, the living grass in contrast to the old, weathered, hard stone. Somehow, for me, this is a hopeful image - that the cold hard reality of death is being swallowed by life and light.', '2015-06-23 11:29:03.000000', NULL, 1),
(7370336, 1153917, 47974, '<td valign="top">To bad you were not centered when you took the photo, it''s off just enough to be distracting.</td>', 'To bad you were not centered when you took the photo, it''s off just enough to be distracting.', '2015-06-23 11:32:50.000000', NULL, 1),
(7370338, 1153221, 47974, '<td valign="top">I really love the perspective and the coloring of the photo but that texture just ruins it for me.  That''s to bad because it could have been a front runner.</td>', 'I really love the perspective and the coloring of the photo but that texture just ruins it for me.  That''s to bad because it could have been a front runner.', '2015-06-23 11:36:09.000000', NULL, 1),
(7370340, 1154400, 47974, '<td valign="top">Really not a fan of over cooked HDR, to bad as this could have been a great shot.</td>', 'Really not a fan of over cooked HDR, to bad as this could have been a great shot.', '2015-06-23 11:36:57.000000', NULL, 1),
(7370343, 1153067, 47974, '<td valign="top">I really like the overall mood of the photo, great job on producing that.  This is an example of the smaller size (not being able to view full resolution photo) being a disadvantage.  I am sure in your original you can zoom in and read the tombstones and for some reason that is what I want to do.  Maybe if you had shot at a bit less of an angle, they would have been big enough to read.</td>', 'I really like the overall mood of the photo, great job on producing that.  This is an example of the smaller size (not being able to view full resolution photo) being a disadvantage.  I am sure in your original you can zoom in and read the tombstones and for some reason that is what I want to do.  Maybe if you had shot at a bit less of an angle, they would have been big enough to read.', '2015-06-23 11:39:58.000000', NULL, 1),
(7370345, 1154544, 47974, '<td valign="top">Really great perspective but the photo is just to cliché.  A little pop from processing and a better sky would have helped it stand out.</td>', 'Really great perspective but the photo is just to cliché.  A little pop from processing and a better sky would have helped it stand out.', '2015-06-23 11:41:08.000000', NULL, 1),
(7370348, 1153263, 47974, '<td valign="top">Love the perspective and the fog is wonderful.  Just there is something missing and I can not put my finger on it.</td>', 'Love the perspective and the fog is wonderful.  Just there is something missing and I can not put my finger on it.', '2015-06-23 11:42:44.000000', NULL, 1),
(7370351, 1153703, 47974, '<td valign="top">Wonderful perspective and it looks like you had a beautiful sky for the shot.  The texture or filter you applied ruins it for me tho.</td>', 'Wonderful perspective and it looks like you had a beautiful sky for the shot.  The texture or filter you applied ruins it for me tho.', '2015-06-23 11:44:21.000000', NULL, 1),
(7370354, 1154436, 47974, '<td valign="top">Great concept and processing.  Hate photos with the skewed look......to bad</td>', 'Great concept and processing.  Hate photos with the skewed look......to bad', '2015-06-23 11:47:14.000000', NULL, 1),
(7370357, 1154192, 47974, '<td valign="top">Love the perspective and processing.  Wish you would have opened up a bit more to get more blur on the background tombstones like those in front.</td>', 'Love the perspective and processing.  Wish you would have opened up a bit more to get more blur on the background tombstones like those in front.', '2015-06-23 11:48:30.000000', NULL, 1),
(7370360, 1153243, 47974, '<td valign="top">Very interesting perspective, I like it.  Would have really rocked with some big puffy white clouds.</td>', 'Very interesting perspective, I like it.  Would have really rocked with some big puffy white clouds.', '2015-06-23 11:52:02.000000', NULL, 1),
(7370365, 1153425, 65234, '<td valign="top">Very pastoral and the colors and detail are nice.  Rather like the far grave that looks like a caricature of a person lying down;  would have had fun trying to do something with that as a focal point.</td>', 'Very pastoral and the colors and detail are nice.  Rather like the far grave that looks like a caricature of a person lying down;  would have had fun trying to do something with that as a focal point.', '2015-06-23 11:56:48.000000', NULL, 1),
(7370366, 1153330, 47974, '<td valign="top">Super interesting grave and I love the processing.  If you had not been on a perfect 45 from it, I think you would have had a stronger composition and would not have blurred out the writing on the left side.  Now, I want to find this so I can photograph it from ground level looking up with my fisheye lens.</td>', 'Super interesting grave and I love the processing.  If you had not been on a perfect 45 from it, I think you would have had a stronger composition and would not have blurred out the writing on the left side.  Now, I want to find this so I can photograph it from ground level looking up with my fisheye lens.', '2015-06-23 11:57:40.000000', NULL, 1),
(7370367, 1154305, 65234, '<td valign="top">Many, many gravestones.  Scenes like this are kind of sad to me, where the individuality of all those people can''t be seen.  Better than those grave markers in the ground, though.</td>', 'Many, many gravestones.  Scenes like this are kind of sad to me, where the individuality of all those people can''t be seen.  Better than those grave markers in the ground, though.', '2015-06-23 11:57:48.000000', NULL, 1),
(7370368, 1154507, 65234, '<td valign="top">Poor Baby Brown :-(  Those sorts of headstones always get me emotionally.  Interesting stone to use as a focal point.</td>', 'Poor Baby Brown :-(  Those sorts of headstones always get me emotionally.  Interesting stone to use as a focal point.', '2015-06-23 11:58:31.000000', NULL, 1),
(7370370, 1154565, 65234, '<td valign="top">One of the many interesting things I see in older graveyards.  The new ones tend to lack personality.  Nice processing here.</td>', 'One of the many interesting things I see in older graveyards.  The new ones tend to lack personality.  Nice processing here.', '2015-06-23 11:59:54.000000', NULL, 1),
(7370371, 1153222, 47974, '<td valign="top">Not a fan of selective desaturation and the pieces of flower laying around in the grass is distracting. You should have removed the color from those pieces.</td>', 'Not a fan of selective desaturation and the pieces of flower laying around in the grass is distracting. You should have removed the color from those pieces.', '2015-06-23 12:00:50.000000', NULL, 1),
(7370372, 1154436, 65234, '<td valign="top">I like the skewed perspective for an other-worldly image.  Would certainly throw me off to see a ghost!</td>', 'I like the skewed perspective for an other-worldly image.  Would certainly throw me off to see a ghost!', '2015-06-23 12:01:15.000000', NULL, 1),
(7370373, 1153261, 65234, '<td valign="top">Poignant.  Children don''t seem like they belong in graveyards.</td>', 'Poignant.  Children don''t seem like they belong in graveyards.', '2015-06-23 12:02:25.000000', NULL, 1),
(7370374, 1154267, 65234, '<td valign="top">Oh, but I want to go in!  I love old graveyards and the stories they tell.</td>', 'Oh, but I want to go in!  I love old graveyards and the stories they tell.', '2015-06-23 12:02:54.000000', NULL, 1),
(7370376, 1154138, 65234, '<td valign="top">IR?  The mausoleum stands out, but the trees are the first thing I noticed.</td>', 'IR?  The mausoleum stands out, but the trees are the first thing I noticed.', '2015-06-23 12:04:19.000000', NULL, 1),
(7370377, 1154351, 65234, '<td valign="top">Wide angle is perfect for this scene, and I like the mistiness.</td>', 'Wide angle is perfect for this scene, and I like the mistiness.', '2015-06-23 12:05:03.000000', NULL, 1),
(7370380, 1153917, 65234, '<td valign="top">Nice find :-)  Although I''m a little creeped out by the person who appears to be staring at us from inside.</td>', 'Nice find :-)  Although I''m a little creeped out by the person who appears to be staring at us from inside.', '2015-06-23 12:05:43.000000', NULL, 1),
(7370381, 1154322, 65234, '<td valign="top">True.  Looks like a lot of graves in a very small space.</td>', 'True.  Looks like a lot of graves in a very small space.', '2015-06-23 12:06:17.000000', NULL, 1),
(7370382, 1153116, 65234, '<td valign="top">Love the processing!</td>', 'Love the processing!', '2015-06-23 12:07:01.000000', NULL, 1),
(7370384, 1153156, 65234, '<td valign="top">Like, hamsters or something?  Weird.</td>', 'Like, hamsters or something?  Weird.', '2015-06-23 12:08:11.000000', NULL, 1),
(7370385, 1154376, 65234, '<td valign="top">The horizon feels askew, but maybe that''s an optical illusion from the swirling clouds on the other side.  Nice clouds, BTW, and I like that you chose an overgrown old stone for the foreground here.</td>', 'The horizon feels askew, but maybe that''s an optical illusion from the swirling clouds on the other side.  Nice clouds, BTW, and I like that you chose an overgrown old stone for the foreground here.', '2015-06-23 12:10:33.000000', NULL, 1),
(7370387, 1154078, 65234, '<td valign="top">That''s just cool!  Wonderfully atmospheric.</td>', 'That''s just cool!  Wonderfully atmospheric.', '2015-06-23 12:11:49.000000', NULL, 1),
(7370389, 1154400, 65234, '<td valign="top">Spanish moss lends such great moodiness to a graveyard.  Subdued colors work well, too.</td>', 'Spanish moss lends such great moodiness to a graveyard.  Subdued colors work well, too.', '2015-06-23 12:16:02.000000', NULL, 1),
(7370403, 1153618, 77185, '<td valign="top">There''s a lot going on here, which I find both good and bad. On one hand, there''s a lot to look at, but on the other, there''s a lot to look at, almost too much. A lot of detail, but my eyes don''t know where to stop.</td>', 'There''s a lot going on here, which I find both good and bad. On one hand, there''s a lot to look at, but on the other, there''s a lot to look at, almost too much. A lot of detail, but my eyes don''t know where to stop.', '2015-06-23 12:33:10.000000', NULL, 1),
(7370405, 1154591, 50864, '<td valign="top">Beautiful light.</td>', 'Beautiful light.', '2015-06-23 12:34:50.000000', NULL, 1),
(7370406, 1154166, 50864, '<td valign="top">Nice take on the challenge.</td>', 'Nice take on the challenge.', '2015-06-23 12:35:10.000000', NULL, 1),
(7370410, 1154591, 70270, '<td valign="top">creepy and haunting.  top pick</td>', 'creepy and haunting.  top pick', '2015-06-23 12:37:47.000000', NULL, 1),
(7370412, 1153506, 70270, '<td valign="top">vintage feel works really well here</td>', 'vintage feel works really well here', '2015-06-23 12:38:15.000000', NULL, 1),
(7370413, 1154166, 77185, '<td valign="top">An interesting scene. I like it, though I wish the person on the right hadn''t been cut off. Then again, I don''t know if it would have worked composition-wise to include him?</td>', 'An interesting scene. I like it, though I wish the person on the right hadn''t been cut off. Then again, I don''t know if it would have worked composition-wise to include him?', '2015-06-23 12:38:29.000000', NULL, 1),
(7370415, 1152686, 70270, '<td valign="top">that is one creepy little girl.</td>', 'that is one creepy little girl.', '2015-06-23 12:38:56.000000', NULL, 1),
(7370416, 1153955, 70270, '<td valign="top">nicely seen serene scene</td>', 'nicely seen serene scene', '2015-06-23 12:39:13.000000', NULL, 1),
(7370417, 1154459, 50864, '<td valign="top">Just lovely. Beautifully photographed and processed.the delicate weeds are a perfect foil to the heavy stones.</td>', 'Just lovely. Beautifully photographed and processed.the delicate weeds are a perfect foil to the heavy stones.', '2015-06-23 12:40:02.000000', NULL, 1),
(7370418, 1154476, 50864, '<td valign="top">Nice rough processing and love the lens flare.</td>', 'Nice rough processing and love the lens flare.', '2015-06-23 12:40:50.000000', NULL, 1),
(7370419, 1154239, 77185, '<td valign="top">Garda lake is one of those places I really want to visit! The photo feels slightly tilted, but it might be due to the land and trees leaning in reality. I really like the green tones.</td>', 'Garda lake is one of those places I really want to visit! The photo feels slightly tilted, but it might be due to the land and trees leaning in reality. I really like the green tones.', '2015-06-23 12:41:07.000000', NULL, 1),
(7370420, 1153821, 50864, '<td valign="top">Very pretty light.</td>', 'Very pretty light.', '2015-06-23 12:41:24.000000', NULL, 1),
(7370421, 1154467, 70270, '<td valign="top">a tilted frame is often just a gimmick to add interest to an otherwise boring shot, but here I think it works really well, because it puts the viewer in the shoes of a visitor to the grave, tilting their head as they look down at the headstone</td>', 'a tilted frame is often just a gimmick to add interest to an otherwise boring shot, but here I think it works really well, because it puts the viewer in the shoes of a visitor to the grave, tilting their head as they look down at the headstone', '2015-06-23 12:42:08.000000', NULL, 1),
(7370422, 1153116, 50864, '<td valign="top">Very lovely processing. The tree adds so much.</td>', 'Very lovely processing. The tree adds so much.', '2015-06-23 12:43:47.000000', NULL, 1),
(7370425, 1154254, 70270, '<td valign="top">The duende is phenomenal - perfectly ethereal.  But the graveyard for me is just too dark, and the different angles of light hitting the headstones distracting.  I think if you would have cropped about a quarter off the left (just to the right of the headstone behind your spirit) and off the bottom (just below the last headstone on the right) it would have been much stronger, and would have pushed this from a 7 to a 10.</td>', 'The duende is phenomenal - perfectly ethereal.  But the graveyard for me is just too dark, and the different angles of light hitting the headstones distracting.  I think if you would have cropped about a quarter off the left (just to the right of the headstone behind your spirit) and off the bottom (just below the last headstone on the right) it would have been much stronger, and would have pushed this from a 7 to a 10.', '2015-06-23 12:48:20.000000', NULL, 1),
(7370426, 1154096, 77185, '<td valign="top">Tragiskt, det är alltid sorgligt att se barns namn på gravstenar och extra när det är två på samma gång...</td>', 'Tragiskt, det är alltid sorgligt att se barns namn på gravstenar och extra när det är två på samma gång...', '2015-06-23 12:49:50.000000', NULL, 1),
